public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    final int N = sc.nextInt();
    int[] Qn = new int[N];
    int[] An = new int[N];
    int[] Bn = new int[N];

    for(int i = 0; i < N; i++){
      Qn[i] = sc.nextInt();
    }
    for(int i = 0; i < N; i++){
      An[i] = sc.nextInt();
    }
    for(int i = 0; i < N; i++){
      Bn[i] = sc.nextInt();
    }

    int maxServings = 0;
    for(int aServings = 0; aServings <= 1000000; aServings++){
      boolean possible = true;
      int maxBServings = Integer.MAX_VALUE;
      for(int j = 0; j < N; j++){
        if(aServings * An[j] > Qn[j]){
          possible = false;
          break;
        }
        int remaining = Qn[j] - aServings * An[j];
        maxBServings = Math.min(maxBServings, remaining / Bn[j]);
      }
      if(!possible) break;
      maxServings = Math.max(maxServings, aServings + maxBServings);
    }

    System.out.println(maxServings);
}
